import{_ as e,o as l,c as t,a2 as i}from"./chunks/framework.BjkiRu3Q.js";const _=JSON.parse('{"title":"Πληροφορίες αφίξεων πτήσεων και πλοίων","description":"","frontmatter":{},"headers":[],"relativePath":"el/plus/arrival-intelligence.md","filePath":"el/plus/arrival-intelligence.md"}'),r={name:"el/plus/arrival-intelligence.md"};function o(s,a,n,c,p,d){return l(),t("div",null,[...a[0]||(a[0]=[i('<h1 id="πληροφοριες-αφιξεων-πτησεων-και-πλοιων" tabindex="-1">Πληροφορίες αφίξεων πτήσεων και πλοίων <a class="header-anchor" href="#πληροφοριες-αφιξεων-πτησεων-και-πλοιων" aria-label="Permalink to &quot;Πληροφορίες αφίξεων πτήσεων και πλοίων&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">Έκδοση αναφοράς</p><p>Έλεγχος πηγαίου κώδικα TransferBook+ v0.7.26. Επιβεβαιώστε εγκατεστημένη έκδοση, εταιρεία, δικαιώματα και ρυθμίσεις. Χρησιμοποιήστε εγκεκριμένα συνθετικά δεδομένα για εκπαίδευση. Δεν επιβεβαιώνεται εμπορική ενεργοποίηση.</p></div><h2 id="ελεγχος-πινακα-αφιξεων" tabindex="-1">Έλεγχος πίνακα αφίξεων <a class="header-anchor" href="#ελεγχος-πινακα-αφιξεων" aria-label="Permalink to &quot;Έλεγχος πίνακα αφίξεων&quot;">​</a></h2><ol><li>Επιλέξτε εξουσιοδοτημένη εταιρεία και περιοχή. Εντοπίστε την κράτηση και το σωστό σκέλος μετάβασης ή επιστροφής στο Arrival Intelligence.</li><li>Επαληθεύστε μεταφορέα/αριθμό δρομολογίου, ημερομηνία, αφετηρία και προορισμό από εγκεκριμένη πηγή. Καταγράψτε ταυτότητα και χειροκίνητη παρατήρηση με χρόνο και τεκμήριο. Μην επινοείτε εκτιμώμενες ή πραγματικές ώρες άφιξης.</li><li>Εξετάστε πρόωρη, καθυστερημένη, ακυρωμένη ή διαταραγμένη άφιξη. Δείτε ιστορικό παρατηρήσεων και ειδοποίηση ανάθεσης. Μην εγκρίνετε νέα απόφαση με παρωχημένο ή αντικατασταθέν τεκμήριο.</li><li>Εγκρίνετε ή απορρίψτε προτεινόμενη αλλαγή παραλαβής μόνο με δικαίωμα ανάθεσης. Ελέγξτε συγκρούσεις, πλήρη διάρκεια, διαθεσιμότητα οδηγού, συντήρηση οχήματος και όρια ημερομηνίας/νυχτερινού ναύλου. Ολοκληρώστε τυχόν απαιτούμενο επανέλεγχο ναύλου.</li><li>Ανοίξτε ξανά κράτηση και πρόγραμμα. Επιβεβαιώστε απόφαση, ανεξάρτητο χρόνο σκέλους και ενημέρωση οδηγού. Μην επιχειρείτε αναστροφή ολοκληρωμένης απόφασης με νέα υποβολή.</li></ol><h2 id="διαθεσιμοτητα-και-εναλλακτικη" tabindex="-1">Διαθεσιμότητα και εναλλακτική <a class="header-anchor" href="#διαθεσιμοτητα-και-εναλλακτικη" aria-label="Permalink to &quot;Διαθεσιμότητα και εναλλακτική&quot;">​</a></h2><p>Οι χειροκίνητες παρατηρήσεις και οι αποφάσεις αποθηκεύονται μόνιμα. Εκκρεμούν αυτόματη εξωτερική παρακολούθηση, εργασίες παρασκηνίου, πλήρης επιβολή ορίων και ενεργοποίηση αδειοδοτημένων χαρτών. Μια καταχώριση παρόχου δεν αποτελεί ζωντανή ροή. Συνεχίστε εγκεκριμένη χειροκίνητη επαλήθευση όταν δεν υπάρχει πάροχος. Η ειδοποίηση δεν εγγυάται την ώρα άφιξης.</p><p>Δείτε <a href="/el/plus/dispatch-schedule.html">Πρόγραμμα αναθέσεων</a> και <a href="/el/integrations/maps-arrivals-setup.html">Ρύθμιση API χαρτών και αφίξεων</a>.</p>',7)])])}const u=e(r,[["render",o]]);export{_ as __pageData,u as default};
